svg.script:
window.onload = function ()
{
    var test = document.querySelectorAll('.provincia');

    for (var i = 0; i < test.length; i++)
    {
        test[i].addEventListener("click", function() {
        // El label está en el path directamente
        let nombreProvincia = this.getAttribute('inkscape:label');

        window.parent.postMessage(
            { tipo: "regionSeleccionada", ubicacion: "ubic_provincia_id", region: nombreProvincia },
            window.location.origin
            );
        });
    }
}
